def _find_card_spans_for_postprocess(s: str):
    """Return card spans (start, body_start, end) for top-level <div class="card"> blocks."""
    import re as _re
    spans, i = [], 0
    pat = _re.compile(r'<div\s+class="card"(?:\s+style="[^"]*")?\s*>')
    while True:
        m = pat.search(s, i)
        if not m:
            break
        start, body_start = m.start(), m.end()
        depth, j = 1, body_start
        while j < len(s) and depth > 0:
            no = s.find('<div', j)
            nc = s.find('</div', j)
            if nc == -1:
                j = len(s); break
            if no != -1 and no < nc:
                depth += 1; j = no + 4
            else:
                depth -= 1; j = nc + 6
        spans.append((start, body_start, j))
        i = j
    return spans


def _card_title_text(card_html: str) -> str:
    import re as _re
    m = _re.search(r'<h2[^>]*>(.*?)</h2>', card_html, flags=_re.I | _re.S)
    if not m:
        return ""
    t = _re.sub(r'<[^>]+>', ' ', m.group(1))
    t = _re.sub(r'&#\d+;', ' ', t)
    t = _re.sub(r'&[a-zA-Z]+;', ' ', t)
    return _re.sub(r'\s+', ' ', t).strip()


def _move_kvb_event_traces_after_footprint(html: str) -> str:
    """Place KV$B Event Traces immediately after KV Cache Footprint section."""
    spans = _find_card_spans_for_postprocess(html)
    if not spans:
        return html
    foot = kvb = None
    for sp in spans:
        card = html[sp[0]:sp[2]]
        title = _card_title_text(card).lower()
        if foot is None and 'kv cache footprint' in title and 'hbm capacity' in title:
            foot = sp
        if kvb is None and ('kv cache block' in title or 'kv$b' in title) and ('event trace' in title or 'event' in title):
            kvb = sp
    if not foot or not kvb or kvb[0] == foot[2]:
        return html
    kvb_html = html[kvb[0]:kvb[2]]
    # Remove KV$B card first, then re-find footprint in the shortened HTML.
    without = html[:kvb[0]] + html[kvb[2]:]
    spans2 = _find_card_spans_for_postprocess(without)
    foot2 = None
    for sp in spans2:
        if 'kv cache footprint' in _card_title_text(without[sp[0]:sp[2]]).lower() and 'hbm capacity' in _card_title_text(without[sp[0]:sp[2]]).lower():
            foot2 = sp; break
    if not foot2:
        return html
    insert_at = foot2[2]
    return without[:insert_at] + "\n" + kvb_html + "\n" + without[insert_at:]


def _remove_duplicate_old_cross_layer_card(html: str) -> str:
    """Deprecated in v1.39.86; retained for compatibility, no-op."""
    return html


def _collapse_l3_sections_no_activity(html: str) -> str:
    """Collapse, but do not remove, L3-only End Report cards for L2-only runs.

    Title-based only: never collapse mixed GPU/HBM/DRAM/cache/latency sections
    just because their body text mentions L3.
    """
    import html as _html
    spans = _find_card_spans_for_postprocess(html)
    if not spans:
        return html
    title_terms = (
        'l3', 'nvme', 'ssd', 'lba', 'hot/cold', 'queue depth',
        'storage i/o', 'kv$ l3', 'physical l3', 'trim / discard'
    )
    keep_if_terms = (
        'gpu', 'hbm', 'dram', 'memory profile', 'kv cache footprint',
        'latency', 'session', 'inference metrics', 'p50', 'p90', 'p99',
        'cache hit', 'setup', 'server configuration', 'optimisation',
        'formula', 'ai operation phase', 'kv cache block', 'kv$b'
    )
    out, last, n = [], 0, 0
    for st, _, en in spans:
        card = html[st:en]
        title = _card_title_text(card).lower()
        should_collapse = any(t in title for t in title_terms) and not any(t in title for t in keep_if_terms)
        if not should_collapse:
            continue
        out.append(html[last:st])
        shown_title = _html.escape(_card_title_text(card) or 'L3 / storage section')
        out.append(
            '\n<details class="card amoprof-l3-collapsed" style="border-color:#94a3b8" data-amoprof-collapsed="l3-no-activity">\n'
            '  <summary style="cursor:pointer;font-weight:800;color:#334155;padding:4px 0">'
            + shown_title +
            ' <span style="font-size:11px;color:#64748b;font-weight:600">— collapsed: L3 not configured / no L3 activity in this run</span></summary>\n'
            '  <div style="font-size:12px;color:#475569;line-height:1.6;margin-top:10px;background:#f8fafc;border-left:3px solid #94a3b8;padding:10px 12px;border-radius:0 6px 6px 0">'
            'This section is retained for report completeness, but it is collapsed because no explicit L3 activity was detected for this run. Expand only when validating collection coverage.'
            '  </div>\n</details>\n'
        )
        last = en
        n += 1
    if n == 0:
        return html
    out.append(html[last:])
    return ''.join(out)


def _collapse_empty_cards(html: str) -> str:
    """Post-process the End Report HTML to collapse cards that have no data.

    Detection (three paths — any one triggers collapse):
      (1) All detected KPI tile values are empty / zero / N/A / nan
      (2) No KPI tiles AND a strong placeholder phrase ("Requires blktrace",
          "not available", "framework only", etc.) appears in the card body
      (3) Some KPI tiles + placeholder phrase + ≥50% of tiles read empty
          (catches mixed cards like NVMe Deep Profiling that have one or two
          theoretical spec values alongside missing runtime measurements)

    Wrapping uses a JavaScript-based show/hide pattern (button + onclick +
    display:none toggle) rather than native <details>. The native approach
    failed in this codebase's rendering environment because the static
    report's DOMContentLoaded reorder script moves all .card elements,
    which disrupts <details>-nested children. The JS-button pattern is
    self-contained, runs in any rendering context, and survives DOM
    reordering since the whole collapsed unit moves as one element.

    Why post-process instead of refactor each card render site? Blast
    radius — the End Report has 25+ distinct card render patterns, and
    matplotlib-PNG sections embed their "Requires blktrace" placeholder
    inside the image (not the HTML), so we can't reliably know empty from
    the data side without duplicating chart-code branching logic.
    """
    import re as _re

    EMPTY_VALUES = {"0.0", "0.00", "0.0%", "0", "0K", "0M", "0B", "0KB", "0MB",
                     "0GB", "0.0KB", "0.0MB", "0.0GB", "0.000", "0.0000",
                     "N/A", "n/a", "NaN", "nan", "\u2014", "-", "No", "no", ""}

    # Phrases that, when found in card body text, mean "this run did not
    # capture the data for this section". Each entry must be unambiguous —
    # we deliberately exclude vague terms like "low" or "minimal" that could
    # appear in valid analysis prose.
    STRONG_PLACEHOLDERS = [
        'requires blktrace',
        'requires biosnoop',
        'requires amduprof',
        'install amduprof',
        'enable with blktrace',
        'enable with biosnoop',
        'not collected',
        'not available',
        'not enabled',
        'no data captured',
        'data unavailable',
        'metric unavailable',
        'collector unavailable',
        'charts show framework only',
        'framework only',
        'enable deep io',
        'no data for',
    ]

    def _value_is_empty(v):
        v2 = _re.sub(r'\s+', '', v)
        if _re.fullmatch(r'0+/0+', v2): return True
        if any(k in v.lower() for k in ['no activity', 'no data',
                                         'not present', 'unavailable', 'n/a']):
            return True
        base = _re.sub(r'[A-Za-z\u00b5%/]+$', '', v2)
        if base in EMPTY_VALUES or v2 in EMPTY_VALUES: return True
        try:
            if float(base) == 0.0: return True
        except (ValueError, TypeError):
            pass
        return False

    def _has_placeholder(card_inner):
        text = _re.sub(r'<[^>]+>', ' ', card_inner)
        text = _re.sub(r'&[a-z#0-9]+;', ' ', text)
        text_lower = text.lower()
        return any(p in text_lower for p in STRONG_PLACEHOLDERS)

    def _find_cards(s):
        spans, i = [], 0
        pat = _re.compile(r'<div\s+class="card"(?:\s+style="[^"]*")?\s*>')
        while True:
            m = pat.search(s, i)
            if not m: break
            start, body_start = m.start(), m.end()
            depth = 1; j = body_start
            while j < len(s) and depth > 0:
                no = s.find('<div', j); nc = s.find('</div', j)
                if nc == -1: j = len(s); break
                if no != -1 and no < nc: depth += 1; j = no + 4
                else: depth -= 1; j = nc + 6
            spans.append((start, body_start, j))
            i = j
        return spans

    def _is_empty(inner):
        vals = [m.group(1).strip() for m in _re.finditer(
                r'font-size:\s*(?:18|20|22|24|26)px[^>]*>([^<]{1,40})<', inner)]
        has_placeholder = _has_placeholder(inner)

        tm = _re.search(r'<h2[^>]*>(.{0,300}?)</h2>', inner, _re.DOTALL)
        if not tm:
            return False, ""
        title = _re.sub(r'<[^>]+>', '', tm.group(1))
        title = _re.sub(r'&#\d+;', '', title)
        title = _re.sub(r'&[a-z]+;', ' ', title)
        title = _re.sub(r'\s+', ' ', title).strip()
        title_l = title.lower()

        # Section-specific guard: DRAM bandwidth can have valid KPI values and/or
        # a synthesized fallback chart even when the raw AMDuProf timeseries is
        # absent. Keep it visible whenever a chart or non-zero DRAM BW/txn value is present.
        if 'system dram' in title_l and ('bandwidth' in title_l or 'transaction' in title_l):
            text = _re.sub(r'<[^>]+>', ' ', inner)
            text = _re.sub(r'&[a-z#0-9]+;', ' ', text)
            text_l = _re.sub(r'\s+', ' ', text.lower())
            has_chart = ('amoprof-chart' in inner or '<img ' in inner or '<svg ' in inner or 'summary fallback' in text_l)
            has_nonzero_bw = _re.search(r'(dram\s+)?(read|write|total|peak)\s*bw[^0-9]{0,80}([1-9]\d*(?:\.\d+)?)\s*(gb/s|mb/s)', text_l) is not None
            has_nonzero_txn = _re.search(r'(read|write)\s*txns?[^0-9]{0,80}([1-9]\d*(?:\.\d+)?)\s*m/s', text_l) is not None
            if has_chart or has_nonzero_bw or has_nonzero_txn:
                return False, ''

        # Section-specific guard: the §E TRIM/Discard card embeds a matplotlib
        # image and also contains non-zero read/write temporal reference values,
        # so the generic KPI-based zero detector may leave it expanded even when
        # there are no discard events.  Treat the section as zero/no-data when
        # the explicit TRIM indicators show no activity.
        if 'trim' in title_l and 'discard' in title_l:
            text = _re.sub(r'<[^>]+>', ' ', inner)
            text = _re.sub(r'&[a-z#0-9]+;', ' ', text)
            text_l = _re.sub(r'\s+', ' ', text.lower())
            has_trim_yes = _re.search(r'trim\s*present\s*yes', text_l) is not None
            has_no_trim = (
                _re.search(r'trim\s*present\s*no', text_l) is not None
                or 'no trim activity observed' in text_l
                or 'no trim' in text_l
            )
            trim_iops_zero = (
                _re.search(r'trim\s*iops\s*0(?:\.0+)?\b', text_l) is not None
                or _re.search(r'iops=0(?:\.0+)?\b', text_l) is not None
            )
            trim_bw_zero = (
                _re.search(r'trim\s*bw\s*0(?:\.0+)?\b', text_l) is not None
                or _re.search(r'bw=0(?:\.0+)?\s*mb/s', text_l) is not None
            )
            if not has_trim_yes and (has_no_trim or (trim_iops_zero and trim_bw_zero)):
                return True, title

        if vals and all(_value_is_empty(v) for v in vals):
            verdict = True
        elif not vals and has_placeholder:
            verdict = True
        elif vals and has_placeholder:
            n_zero = sum(1 for v in vals if _value_is_empty(v))
            verdict = (n_zero / len(vals)) >= 0.5
        else:
            verdict = False

        if not verdict:
            return False, ""

        return True, title

    def _make_wrap(title, inner_no_h2):
        # Button + onclick that flips display style on its next sibling div.
        # Inline-style everything so this works regardless of what CSS is
        # already loaded in the page. `all:unset` neutralizes any existing
        # button styling that would otherwise interfere.
        return (
            '<div class="card amoprof-jscollapse" '
            'style="padding:0;background:#111827;border:1px solid #334155;'
            'border-radius:12px;margin:14px 0;overflow:hidden">'
            '<button type="button" '
            'onclick="var n=this.nextElementSibling;'
            "var a=this.querySelector(\'.amoprof-arrow\');"
            "if(n.style.display===\'none\'||!n.style.display){"
              "n.style.display=\'block\';a.textContent=\'\u25be\';"
              "this.querySelector(\'.amoprof-hint\').style.display=\'none\';"
            "}else{"
              "n.style.display=\'none\';a.textContent=\'\u25b8\';"
              "this.querySelector(\'.amoprof-hint\').style.display=\'inline\';"
            "}\" "
            'style="all:unset;box-sizing:border-box;display:flex;'
            'align-items:center;gap:10px;width:100%;padding:12px 16px;'
            'cursor:pointer;color:#f8fafc;font-family:inherit;'
            'background:transparent;border:none;text-align:left">'
            '<span class="amoprof-arrow" '
            'style="color:#93c5fd;font-size:14px;font-weight:bold">\u25b8</span>'
            '<span style="flex:1;font-weight:700;font-size:13px;color:#f8fafc">'
            + title + '</span>'
            '<span style="font-size:10px;font-weight:900;letter-spacing:.6px;'
            'text-transform:uppercase;border-radius:999px;padding:3px 8px;'
            'color:#fde68a;background:#78350f;border:1px solid #92400e">'
            'ZERO DATA</span>'
            '<span class="amoprof-hint" style="color:#94a3b8;font-size:11px;'
            'font-style:italic;white-space:nowrap">click to expand</span>'
            '</button>'
            '<div style="display:none;padding:16px 18px;background:#1e293b;'
            'border-top:1px solid #334155">'
            + inner_no_h2 +
            '</div>'
            '</div>'
        )

    spans = _find_cards(html)
    if not spans:
        return html

    out, last = [], 0
    for start, body_start, end in spans:
        out.append(html[last:start])
        inner = html[body_start:end - 6]
        empty, title = _is_empty(inner)
        if empty and title:
            inner_no_h2 = _re.sub(
                r'<h2[^>]*>.{0,300}?</h2>\s*', '', inner,
                count=1, flags=_re.DOTALL)
            out.append(_make_wrap(title, inner_no_h2))
        else:
            out.append(html[start:end])
        last = end
    out.append(html[last:])
    return ''.join(out)


# ── Main ──────────────────────────────────────────────────────────────────────

# ── Excel generation ──────────────────────────────────────────────────────────

def generate_excel(m: Metrics, bottlenecks: list[dict], recs: list[dict],
                   run_label: str, out_path: Path):
    """Build a full multi-sheet Excel workbook with native charts."""
    from openpyxl import Workbook
    from openpyxl.styles import (Font, PatternFill, Alignment, Border, Side,
                                  GradientFill)
    from openpyxl.utils import get_column_letter
    from openpyxl.chart import BarChart, LineChart, RadarChart, PieChart, AreaChart, Reference
    from openpyxl.chart.series import SeriesLabel
    from openpyxl.chart.layout import Layout
    from openpyxl.formatting.rule import ColorScaleRule, DataBarRule
    from openpyxl.styles.numbers import FORMAT_PERCENTAGE_00

    wb = Workbook()
    wb.remove(wb.active)  # remove default sheet

    # ── Shared style helpers ──────────────────────────────────────────────────
    FONT_NAME = "Arial"

    def hdr_font(sz=11, bold=True, color="FFFFFF"):
        return Font(name=FONT_NAME, size=sz, bold=bold, color=color)

    def body_font(sz=10, bold=False, color="000000"):
        return Font(name=FONT_NAME, size=sz, bold=bold, color=color)

    def fill(hex_color):
        return PatternFill("solid", fgColor=hex_color)

    def border(style="thin"):
        s = Side(style=style, color="CCCCCC")
        return Border(left=s, right=s, top=s, bottom=s)

    def center():
        return Alignment(horizontal="center", vertical="center", wrap_text=True)

    def left():
        return Alignment(horizontal="left", vertical="center", wrap_text=True)

    # Colour palette (Excel hex, no leading #)
    COL_DARK   = "0D1117"
    COL_HDR    = "1E3A5F"   # deep navy header
    COL_HDR2   = "2D5986"   # secondary header
    COL_PREFIL = "C0392B"   # prefill red-orange
    COL_DECODE = "0E86D4"   # decode blue
    COL_GPU    = "7B68EE"   # medium slate blue
    COL_HBM    = "6A0DAD"   # purple
    COL_DRAM   = "27AE60"   # green
    COL_NVME   = "E74C3C"   # red
    COL_POWER  = "E67E22"   # orange
    COL_OK     = "1E8449"   # dark green
    COL_WARN   = "922B21"   # dark red
    COL_CAU    = "9A7D0A"   # dark yellow
    COL_ZEBRA  = "F2F6FC"   # light blue-grey zebra
    COL_ACCENT = "5B8DB8"   # medium blue
    COL_WHITE  = "FFFFFF"
    COL_BLACK  = "000000"

    SEV_COLORS = {"HIGH": (COL_WARN, "FFC0CB"), "MED": ("7D6608", "FFF9C4"), "LOW": (COL_OK, "D5F5E3")}

    def write_title_block(ws, title, subtitle, row=1):
        ws.merge_cells(f"A{row}:J{row}")
        ws[f"A{row}"] = title
        ws[f"A{row}"].font = Font(name=FONT_NAME, size=16, bold=True, color=COL_WHITE)
        ws[f"A{row}"].fill = fill(COL_HDR)
        ws[f"A{row}"].alignment = center()
        ws.row_dimensions[row].height = 28

        ws.merge_cells(f"A{row+1}:J{row+1}")
        ws[f"A{row+1}"] = subtitle
        ws[f"A{row+1}"].font = Font(name=FONT_NAME, size=10, color="AAAAAA")
        ws[f"A{row+1}"].fill = fill("1A1A2E")
        ws[f"A{row+1}"].alignment = center()
        ws.row_dimensions[row+1].height = 16
        return row + 3

    def write_section_header(ws, text, row, col_span="A:J", color=COL_HDR2):
        ws.merge_cells(f"A{row}:{col_span.split(':')[1]}{row}")
        ws[f"A{row}"] = text
        ws[f"A{row}"].font = hdr_font(10)
        ws[f"A{row}"].fill = fill(color)
        ws[f"A{row}"].alignment = left()
        ws.row_dimensions[row].height = 18
        return row + 1

    def write_table_header(ws, headers: list, row: int, col_start=1):
        for ci, h in enumerate(headers, col_start):
            c = ws.cell(row=row, column=ci, value=h)
            c.font = hdr_font(10)
            c.fill = fill(COL_HDR)
            c.alignment = center()
            c.border = border()
        ws.row_dimensions[row].height = 18
        return row + 1

    def write_kv_pair(ws, row, label, value, unit="", label_col=COL_HDR2, val_color=COL_BLACK):
        ws.cell(row=row, column=1, value=label).font = Font(name=FONT_NAME, size=10, bold=True, color=COL_WHITE)
        ws.cell(row=row, column=1).fill = fill(label_col)
        ws.cell(row=row, column=1).alignment = left()
        v_cell = ws.cell(row=row, column=2, value=f"{value}{' '+unit if unit else ''}")
        v_cell.font = Font(name=FONT_NAME, size=11, bold=True, color=val_color)
        v_cell.alignment = left()
        ws.row_dimensions[row].height = 16

    # ── Sheet 1: Summary ──────────────────────────────────────────────────────
    ws = wb.create_sheet("Summary")
    ws.sheet_view.showGridLines = False
    ws.column_dimensions["A"].width = 28
    ws.column_dimensions["B"].width = 22
    ws.column_dimensions["C"].width = 18
    ws.column_dimensions["D"].width = 18
    ws.column_dimensions["E"].width = 14
    ws.column_dimensions["F"].width = 40

    r = write_title_block(ws, "AI Stack Workload Bottleneck Report",
                          f"Model: {m.model}  |  Run: {run_label}  |  Duration: {m.run_duration_s/60:.0f}m")

    # KPI section
    r = write_section_header(ws, "  KEY PERFORMANCE INDICATORS", r)
    kpis = [
        ("Time to First Token (TTFT mean)", f"{m.ttft_ms:.0f} ms", "Prefill Phase", COL_PREFIL),
        ("Time to First Token (TTFT p50)", f"{(m.sess_ttft_p50_ms or m.ttft_ms):.0f} ms", "Prefill Phase", COL_PREFIL),
        ("Time per Output Token (TPOT mean)", f"{m.tpot_ms:.1f} ms/tok", "Decode Phase", COL_DECODE),
        ("Time per Output Token (TPOT p50)", f"{(m.sess_tpot_p50_ms or m.tpot_ms):.1f} ms/tok", "Decode Phase", COL_DECODE),
        ("Generation Throughput (mean)", f"{(m.gen_tp_mean or m.gen_tp_peak):.1f} tok/s", "Decode", COL_GPU),
        ("Generation Throughput (p50)", f"{(m.gen_tp_p50 or m.gen_tp_mean or m.gen_tp_peak):.1f} tok/s", "Decode", COL_GPU),
        ("Peak Gen Throughput", f"{m.gen_tp_peak:.1f} tok/s", "Decode", COL_GPU),
        ("E2E Request Latency", f"{m.e2e_ms/1000:.1f} s", "Full Request", COL_ACCENT),
        ("Effective Cache Hit Rate", f"{m.cache_hit_pct:.1f}%", "KV Cache", "1E8449"),
        ("HBM Utilisation (per GPU)", f"{m.hbm_util_pct:.1f}%  ({m.hbm_used_mb_mean/1024:.1f}/{m.hbm_total_mb/1024:.0f} GB)", "GPU Memory", COL_HBM),
        ("GPU Utilisation (mean)", f"{m.gpu_util_mean:.1f}%  (peak {m.gpu_util_peak:.0f}%)", "Compute", COL_GPU),
        ("DRAM Utilisation", f"{m.dram_util_pct:.1f}%  ({m.dram_used_gb:.0f}/{m.dram_total_gb:.0f} GB)", "System Memory", COL_DRAM),
        ("NVMe Write IOPS (max)", f"{m.nvme_wr_iops_max:.0f}", "Storage", COL_NVME),
        ("GPU Power (mean total)", f"{m.gpu_power_mean_w:.0f} W  (peak {m.gpu_power_peak_w:.0f} W/GPU)", "Power", COL_POWER),
    ]
    write_table_header(ws, ["Metric", "Value", "Domain", "Notes"], r)
    r += 1
    for i, (metric, val, domain, color) in enumerate(kpis):
        bg = COL_ZEBRA if i % 2 == 0 else COL_WHITE
        for ci, v in enumerate([metric, val, domain], 1):
            c = ws.cell(row=r, column=ci, value=v)
            c.font = Font(name=FONT_NAME, size=10,
                          bold=(ci == 2), color=color if ci == 2 else COL_BLACK)
            c.fill = fill(bg)
            c.alignment = left() if ci != 2 else center()
            c.border = border()
        ws.row_dimensions[r].height = 16
        r += 1

    r += 1

    # Token composition section
    r = write_section_header(ws, "  CONTEXT TOKEN COMPOSITION", r)
    total_ctx = m.prefill_cache_tokens + m.prefill_compute_tokens + m.decode_tokens
    write_table_header(ws, ["Token Category", "Count", "% of Context", "Phase"], r)
    r += 1
    tok_rows = [
        ("Prefill — Cached (KV hit)", m.prefill_cache_tokens, COL_DECODE),
        ("Prefill — Compute (new)", m.prefill_compute_tokens, COL_PREFIL),
        ("Decode — Generated Output", m.decode_tokens, COL_GPU),
    ]
    for i, (label, cnt, color) in enumerate(tok_rows):
        pct = cnt / total_ctx * 100 if total_ctx > 0 else 0
        bg = COL_ZEBRA if i % 2 == 0 else COL_WHITE
        for ci, v in enumerate([label, cnt, f"{pct:.1f}%",
                                  "Prefill" if i < 2 else "Decode"], 1):
            c = ws.cell(row=r, column=ci, value=v)
            c.font = Font(name=FONT_NAME, size=10, bold=(ci == 2), color=color if ci == 2 else COL_BLACK)
            c.fill = fill(bg)
            c.border = border()
            c.alignment = center() if ci > 1 else left()
        r += 1
    # Total row
    total_row = r
    for ci, v in enumerate(["TOTAL", total_ctx, "100%", ""], 1):
        c = ws.cell(row=r, column=ci, value=v)
        c.font = Font(name=FONT_NAME, size=10, bold=True, color=COL_WHITE)
        c.fill = fill(COL_HDR)
        c.border = border()
        c.alignment = center() if ci > 1 else left()
    r += 2

    # Bottleneck quick summary
    r = write_section_header(ws, "  BOTTLENECK SUMMARY (top 5)", r)
    write_table_header(ws, ["Rank", "Layer", "Score (0–100)", "Phase", "Severity", "Key Detail"], r)
    r += 1
    for rank, b in enumerate(bottlenecks[:5], 1):
        sev = b["severity"]
        sev_fg, sev_bg = SEV_COLORS.get(sev, (COL_BLACK, COL_WHITE))
        bg = COL_ZEBRA if rank % 2 == 0 else COL_WHITE
        for ci, v in enumerate([rank, b["layer"], b["score"], b["phase"], sev, b["detail"][:80]], 1):
            c = ws.cell(row=r, column=ci, value=v)
            if ci == 5:  # severity badge
                c.font = Font(name=FONT_NAME, size=10, bold=True, color=COL_WHITE)
                c.fill = fill(sev_fg)
            elif ci == 3:  # score
                c.font = Font(name=FONT_NAME, size=10, bold=True,
                              color=COL_WARN if b["score"] > 60 else COL_CAU if b["score"] > 30 else COL_OK)
                c.fill = fill(bg)
            else:
                c.font = body_font()
                c.fill = fill(bg)
            c.border = border()
            c.alignment = center() if ci in (1, 3, 4, 5) else left()
        ws.row_dimensions[r].height = 16
        r += 1

    # Bottleneck bar chart on Summary sheet
    bn_data_start = r + 2
    ws.cell(row=bn_data_start, column=1, value="Layer").font = hdr_font(9)
    ws.cell(row=bn_data_start, column=2, value="Score").font = hdr_font(9)
    for i, b in enumerate(bottlenecks):
        ws.cell(row=bn_data_start + 1 + i, column=1, value=b["layer"])
        ws.cell(row=bn_data_start + 1 + i, column=2, value=b["score"])

    chart_bn = BarChart()
    chart_bn.type = "bar"  # horizontal
    chart_bn.title = "Bottleneck Score by Stack Layer"
    chart_bn.y_axis.title = "Layer"
    chart_bn.x_axis.title = "Score (0–100)"
    chart_bn.style = 10
    chart_bn.width = 18
    chart_bn.height = 12
    data_ref = Reference(ws, min_col=2, min_row=bn_data_start,
                         max_row=bn_data_start + len(bottlenecks))
    cats_ref = Reference(ws, min_col=1, min_row=bn_data_start + 1,
                         max_row=bn_data_start + len(bottlenecks))
    chart_bn.add_data(data_ref, titles_from_data=True)
    chart_bn.set_categories(cats_ref)
    chart_bn.series[0].graphicalProperties.solidFill = "5B8DB8"
    ws.add_chart(chart_bn, f"H{r + 1}")

    # ── Sheet 2: Inference ────────────────────────────────────────────────────
    ws2 = wb.create_sheet("Inference")
    ws2.sheet_view.showGridLines = False
    for col, w in [("A", 10), ("B", 16), ("C", 16), ("D", 16), ("E", 16)]:
        ws2.column_dimensions[col].width = w

    r2 = write_title_block(ws2, "SGLang Inference Metrics",
                           f"Model: {m.model}  |  TTFT: {m.ttft_ms:.0f}ms  |  TPOT: {m.tpot_ms:.1f}ms/tok")

    sdf = m.sglang_ts
    tp_col = _find_metric_col(sdf, "gen_throughput") if isinstance(sdf, pd.DataFrame) else None
    run_col = _find_metric_col(sdf, "num_running_reqs") if isinstance(sdf, pd.DataFrame) else None
    tok_col = (_find_metric_col(sdf, "full_token_usage") or _find_metric_col(sdf, "token_usage")) if isinstance(sdf, pd.DataFrame) else None

    if not sdf.empty and tp_col:
        sdf_ds = downsample(sdf, 300)
        r2 = write_section_header(ws2, "  TIMESERIES DATA", r2)
        headers = ["Time (s)", "Gen Throughput (tok/s)", "Running Reqs", "Token Pool Usage"]
        write_table_header(ws2, headers, r2)
        r2 += 1
        data_row_start = r2
        for i, row_d in sdf_ds.iterrows():
            bg = COL_ZEBRA if (r2 - data_row_start) % 2 == 0 else COL_WHITE
            vals = [
                round(float(row_d["time_sec"]), 1),
                round(float(row_d.get(tp_col, 0)), 3),
                round(float(row_d.get(run_col, 0)), 1),
                round(float(row_d.get(tok_col, 0)), 3),
            ]
            for ci, v in enumerate(vals, 1):
                c = ws2.cell(row=r2, column=ci, value=v)
                c.font = body_font(9)
                c.fill = fill(bg)
                c.border = border()
                c.alignment = center()
            r2 += 1
        data_row_end = r2 - 1

        # Line chart: Gen Throughput
        ch1 = LineChart()
        ch1.title = "Generation Throughput (tok/s) Over Time"
        ch1.style = 10
        ch1.y_axis.title = "tok/s"
        ch1.x_axis.title = "Time (s)"
        ch1.width = 20; ch1.height = 10
        d_ref = Reference(ws2, min_col=2, min_row=data_row_start - 1, max_row=data_row_end)
